import icons from "@/data/tech-icons.json";
import { cn } from "@/lib/utils";

type IconEntry = { light: string; dark?: string };

/**
 * Static tech logo from public/icons (generated by `npm run icons`).
 * Plain <img>: SVGs gain nothing from next/image, and the browser caches each
 * file once even when a logo repeats across cards. Light/dark variants are
 * swapped with CSS, so it renders on the server with no theme flicker.
 */
export function TechIcon({ name, className }: { name: string; className?: string }) {
  const icon = (icons as Record<string, IconEntry>)[name];
  if (!icon) return null;

  return (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={icon.light}
        alt=""
        width={20}
        height={20}
        loading="lazy"
        decoding="async"
        className={cn("size-full", icon.dark && "dark:hidden", className)}
      />
      {icon.dark && (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={icon.dark}
          alt=""
          width={20}
          height={20}
          loading="lazy"
          decoding="async"
          className={cn("hidden size-full dark:block", className)}
        />
      )}
    </>
  );
}
